        require(recipient != address(c));
        require(address(this).balance >= amount);

        // fund contract so it can pay rewards
        address(c).call{value: amount}("");

        // give this test contract a positive reward balance for recipient
        c.getFirstWithdrawalBonus(recipient);

        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If this test contract is the recipient, the external call to it succeeds (receive exists),
        // so after a successful first bonus, the reward balance is zero and the call should succeed.
        // If the recipient is some other address that rejects Ether, the call reverts.
        if (recipient == address(this)) {
            assert(!reverted);
        } else {
            assert(reverted == (amount > 0) ? true : !reverted);
        }
    }

    receive() external payable {}
}

