contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        require(recipient != address(0), "recipient must be nonzero");
        require(recipient != address(c), "recipient must not be the contract itself");

        // Ensure the contract has no initial balance so the first withdrawal cannot succeed
        // by paying out existing Ether that does not belong to the recipient.
        uint256 beforeRecipientBalance = recipient.balance;
        uint256 beforeRewards = 0; // no public getter; we rely on observable effects only
        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRecipientBalance = recipient.balance;
        uint256 afterContractBalance = address(c).balance;

        // General rule: the first call must not revert. Because the forwarding
        // call sends 100 wei to the recipient if the recipient accepts Ether,
        // the recipient's balance must increase by exactly 100. If the recipient
        // rejects Ether, the whole first call reverts and no bonus is granted.
        // This harness can only be called with a recipient that accepts Ether,
        // so the deciding assertion is that no revert occurred and exactly 100 wei moved.
        assert(!reverted && afterRecipientBalance >= beforeRecipientBalance &&
               afterRecipientBalance - beforeRecipientBalance == 100 &&
               address(c).balance == afterContractBalance);
    }

    receive() external payable {}
}

