contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient != address(0), "recipient must not be zero address");

        // Recipient that rejects all Ether transfers: used for the deciding call.
        address rejectingRecipient = address(this);

        // Fund c so that a bonus payment could be attempted.
        (bool funded, ) = address(c).call{value: 200}("");
        require(funded, "funding c failed");

        // Deciding call: attempt to claim the bonus for a recipient that rejects Ether.
        bool reverted;
        try c.getFirstWithdrawalBonus(rejectingRecipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: because the recipient (this contract) rejects Ether, the payout fails,
        // so the bonus claim must revert. If it had completed, the recipient's bonus
        // would have been marked claimed and a later claim would be blocked by the
        // already-claimed guard; we check that the claim can still be attempted again
        // without the already-claimed guard being the immediate revert reason.
        assert(reverted);
    }

    receive() external payable {
        // Reject all Ether transfers so withdrawReward's call fails.
        revert("rejecting Ether");
    }
}

