    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        // Precondition: caller has no pending reward so the transfer amount is zero.
        // (No public getter for rewardsForA, so we cannot require it directly; instead
        // we only call withdrawReward directly, which uses whatever reward is stored,
        // but for a fresh contract with no prior setup the reward is zero.)

        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: on a fresh contract, a direct call to withdrawReward with a
        // recipient that has never received a reward must succeed, transfer no Ether,
        // and clear the reentrancy lock.
        assert(!reverted && address(c).balance == balBefore && !c._locked());
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // Give the recipient a pending reward via the public bonus entry point.
        c.getFirstWithdrawalBonus{value: 0}(recipient);

        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The reentrancy lock must be released whether the transfer succeeded or failed.
        assert(!c._locked());

        // If the call succeeded, c's Ether balance must have decreased by exactly the
        // pending reward that was set up (100 wei), because the transfer to the
        // recipient was successful.
        if (!reverted) {
            assert(address(c).balance == balBefore - 100);
        }
    }

    receive() external payable {}
}

