    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address recipient) public payable {
        require(recipient != address(0));

        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: on a fresh contract, the nonReentrant lock is initially
        // cleared, so a direct withdrawReward call cannot revert solely because
        // the lock is set. Since the recipient has no pending reward (amount 0),
        // an EOA should accept the zero-value call, so the call must succeed.
        assert(!reverted);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address recipient) public payable {
        require(recipient != address(0));

        uint balanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;

        // General rule: on a fresh contract the recipient has no pending reward,
        // so the amount to withdraw is zero. A zero-value call to an address that
        // accepts zero-value Ether must succeed and leave C's Ether balance unchanged.
        assert(!reverted && balanceAfter == balanceBefore);
    }
}

