        uint balanceAfter = address(c).balance;

        // On a fresh contract the recipient has no pending reward, so
        // amountToWithdraw is 0. The zero-value call either succeeds (recipient
        // accepts zero-value Ether) and C's balance is unchanged, or it reverts
        // (recipient rejects the zero-value transfer); in both cases C's balance
