        uint beforeBalance = address(c).balance;
        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        if (!firstReverted) {
            try c.getFirstWithdrawalBonus(recipient) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
