contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient != address(0), "recipient must be nonzero");

        // First call: drives the claimed state if it succeeds.
        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) { firstReverted = false; } catch { firstReverted = true; }

        // Observe whether the recipient is now marked as claimed via a second call.
        bool secondReverted;
        try c.getFirstWithdrawalBonus(recipient) { secondReverted = false; } catch { secondReverted = true; }

        // General rule: If the first call succeeded (so recipient was marked claimed),
        // then any later getFirstWithdrawalBonus for that recipient must revert.
        // Conversely, if the first call reverted, the second call must not be blocked
        // by the recipient already being claimed (it may revert for other reasons,
        // but a call on a non-claimed recipient must not revert *solely* due to claimed state).
        // Expressed observably: the second call reverts exactly when the first call succeeded.
        assert(secondReverted == !firstReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient != address(this), "recipient must not be the test contract");
        require(address(c).balance >= 100, "C must have at least 100 wei for a successful bonus call");

        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) { firstReverted = false; } catch { firstReverted = true; }

        bool secondReverted;
        try c.getFirstWithdrawalBonus(recipient) { secondReverted = false; } catch { secondReverted = true; }

        bool withdrawalReverted;
        try c.withdrawReward(recipient) { withdrawalReverted = false; } catch { withdrawalReverted = true; }

        assert(secondReverted || !withdrawalReverted);
    }

    receive() external payable {}
}

